// SocketsHttpHandler ConnectCallback validates the actual IP being connected (defeats DNS rebinding)
var handler = new SocketsHttpHandler
{
    AllowAutoRedirect = false,
    ConnectTimeout = TimeSpan.FromSeconds(3),
    ConnectCallback = async (ctx, ct) =>
    {
        var addresses = await Dns.GetHostAddressesAsync(ctx.DnsEndPoint.Host, ct);
        var ip = addresses.FirstOrDefault(a => !IsBlocked(a)) ?? throw new HttpRequestException("Destination not allowed");
        var socket = new Socket(ip.AddressFamily, SocketType.Stream, ProtocolType.Tcp);
        await socket.ConnectAsync(new IPEndPoint(ip, ctx.DnsEndPoint.Port), ct);
        return new NetworkStream(socket, ownsSocket: true);
    }
};

static bool IsBlocked(IPAddress ip)
{
    if (ip.IsIPv4MappedToIPv6) ip = ip.MapToIPv4();
    if (IPAddress.IsLoopback(ip) || ip.IsIPv6LinkLocal || ip.IsIPv6SiteLocal) return true;
    var b = ip.GetAddressBytes();
    return ip.AddressFamily == AddressFamily.InterNetwork && (
        b[0] == 10 || (b[0] == 172 && b[1] >= 16 && b[1] <= 31) || (b[0] == 192 && b[1] == 168) ||
        (b[0] == 169 && b[1] == 254) || b[0] == 127 || b[0] == 0 || (b[0] == 100 && b[1] >= 64 && b[1] <= 127));
}
