~~~csharp
public static class FieldCrypto
{
    // AES-256-GCM with random 96-bit nonce and AAD binding ciphertext to its record
    public static byte[] Encrypt(byte[] key, byte[] plaintext, string recordId, byte keyVersion)
    {
        var nonce = RandomNumberGenerator.GetBytes(AesGcm.NonceByteSizes.MaxSize);   // 12 bytes, never reused with a key
        var cipher = new byte[plaintext.Length];
        var tag = new byte[AesGcm.TagByteSizes.MaxSize];
        using var aes = new AesGcm(key, tag.Length);
        aes.Encrypt(nonce, plaintext, cipher, tag, associatedData: Encoding.UTF8.GetBytes(recordId));
        return [keyVersion, .. nonce, .. tag, .. cipher];                               // version enables rotation
    }

    public static byte[] Decrypt(Func<byte, byte[]> keyByVersion, byte[] blob, string recordId)
    {
        var key = keyByVersion(blob[0]);
        var nonce = blob.AsSpan(1, 12); var tag = blob.AsSpan(13, 16); var cipher = blob.AsSpan(29);
        var plain = new byte[cipher.Length];
        using var aes = new AesGcm(key, 16);
        aes.Decrypt(nonce, cipher, tag, plain, Encoding.UTF8.GetBytes(recordId));       // throws if tampered or wrong record
        return plain;
    }
}
