{
    using var ms = new MemoryStream();
    await req.Body.CopyToAsync(ms, ct);
    var body = ms.ToArray();                                                   // raw bytes, verify before parsing

    var ts = req.Headers["X-Signature-Timestamp"].ToString();
    var sig = Convert.FromHexString(req.Headers["X-Signature"].ToString());
    if (!long.TryParse(ts, out var unix) || Math.Abs(DateTimeOffset.UtcNow.ToUnixTimeSeconds() - unix) > 300)
        return Results.Unauthorized();                                         // replay window

    var signed = Encoding.UTF8.GetBytes(ts + ".").Concat(body).ToArray();
    var valid = (await secrets.ActiveAsync(ct)).Any(secret =>                  // multiple keys during rotation
        CryptographicOperations.FixedTimeEquals(HMACSHA256.HashData(secret, signed), sig));
    if (!valid) { metrics.WebhookSignatureFailures.Add(1); return Results.Unauthorized(); }

    var evt = JsonSerializer.Deserialize<ProviderEvent>(body)!;
    if (!await inbox.TryAcceptAsync(evt.Id, body, ct)) return Results.Ok();   // duplicate: acknowledge
