public sealed class EnvelopeEncryptor(CryptographyClient kek)        // Azure.Security.KeyVault.Keys.Cryptography
{
    public async Task<EncryptedBlob> EncryptAsync(byte[] plaintext, string context, CancellationToken ct)
    {
        var dek = RandomNumberGenerator.GetBytes(32);
        try
        {
            var wrapped = await kek.WrapKeyAsync(KeyWrapAlgorithm.RsaOaep256, dek, ct);       // KEK stays in HSM
            var cipher = FieldCrypto.Encrypt(dek, plaintext, context, keyVersion: 1);
            return new EncryptedBlob(cipher, wrapped.EncryptedKey, wrapped.KeyId);              // KeyId includes KEK version
        }
        finally { CryptographicOperations.ZeroMemory(dek); }
    }

    public async Task<byte[]> DecryptAsync(EncryptedBlob blob, string context, CancellationToken ct)
    {
        var dek = (await kek.UnwrapKeyAsync(KeyWrapAlgorithm.RsaOaep256, blob.WrappedDek, ct)).Key;   // authorised + audited
        try { return FieldCrypto.Decrypt(_ => dek, blob.Ciphertext, context); }
        finally { CryptographicOperations.ZeroMemory(dek); }
    }
}
