public static Priority Prioritise(Finding f, Asset a)
{
    var exploited = f.InKev || f.Epss >= 0.5;
    var exposed = a.Exposure == Exposure.Internet;
    var critical = a.Tier == 1 || a.DataClass is DataClass.Card or DataClass.Personal;
    var reachable = f.Reachability != Reachability.NotReachable;

    return (exploited, exposed, critical, reachable, f.Cvss) switch
    {
        (true, true, _, true, _)                 => Priority.P1,   // 72h
        (true, _, true, true, _)                 => Priority.P1,
        (_, true, true, true, >= 7.0)            => Priority.P2,   // 14d
        (_, _, _, true, >= 7.0)                  => Priority.P3,   // 60d
        (_, _, _, false, _)                      => Priority.P4,   // routine
        _                                        => Priority.P3
    };
}
