app.MapPost("/v1/payments", async (HttpRequest http, PaymentRequest req, ClaimsPrincipal client, IPaymentGuard guard, IPaymentService svc, CancellationToken ct) =>
{
    // 1. Detached JWS over the raw body, signed with the client's registered key
    if (!await guard.VerifyDetachedSignatureAsync(http, client.GetClientId(), ct)) return Results.Unauthorized();

    // 2. Idempotency key required
    if (!Guid.TryParse(http.Headers["Idempotency-Key"], out var idem)) return Results.BadRequest("Idempotency-Key required");

    // 3. Ownership and limits
    if (!await guard.ClientOwnsAccountAsync(client.GetClientId(), req.DebtorAccount, ct)) return Results.NotFound();
    var limit = await guard.CheckLimitsAsync(client.GetClientId(), req, ct);
    if (!limit.Allowed) return Results.Problem(limit.Reason, statusCode: 422);

    // 4. Business screening before acceptance; approval required above threshold
    var result = await svc.InitiateAsync(req, idem, client.GetClientId(), requireApproval: req.Amount > limit.ApprovalThreshold, ct);
    return Results.Accepted($"/v1/payments/{result.PaymentId}", result);
}).RequireAuthorization("payments.initiate").RequireRateLimiting("per-client");
