app.MapPost("/payments/{id:guid}/confirm", async (Guid id, ConfirmRequest req, ClaimsPrincipal user, IPaymentStore store, IWebAuthn webauthn, CancellationToken ct) =>
{
    var p = await store.GetPendingAsync(id, user.GetCustomerId(), ct);
