    var expectedChallenge = SHA256.HashData(Encoding.UTF8.GetBytes($"{p.Id}|{p.Amount:F2}|{p.Currency}|{p.PayeeIban}|{p.ChallengeNonce}"));
    var verified = await webauthn.VerifyAssertionAsync(user.GetCustomerId(), req.Assertion, expectedChallenge, ct);   // origin-bound passkey
    if (!verified) return Results.Unauthorized();

    await store.MarkAuthorisedAsync(p.Id, scaMethod: "passkey", ct);   // audit: method, device, time
    return Results.Accepted();
}).RequireAuthorization();
