// Zip bomb defence while extracting statement imports
public static async Task ExtractSafelyAsync(Stream zipStream, string target, CancellationToken ct)
{
    const long maxTotal = 200L * 1024 * 1024; const int maxEntries = 500; const double maxRatio = 100;
    using var zip = new ZipArchive(zipStream, ZipArchiveMode.Read);
    if (zip.Entries.Count > maxEntries) throw new InvalidDataException("Too many entries");
    long total = 0;
    foreach (var e in zip.Entries)
    {
        if (e.FullName.Contains("..") || Path.IsPathRooted(e.FullName)) throw new InvalidDataException("Path traversal");
        if (e.CompressedLength > 0 && (double)e.Length / e.CompressedLength > maxRatio) throw new InvalidDataException("Suspicious ratio");
        total += e.Length;
        if (total > maxTotal) throw new InvalidDataException("Archive too large");
        await using var src = e.Open();
        await using var dst = File.Create(Path.Combine(target, Path.GetFileName(e.FullName)));
        await src.CopyToAsync(dst, ct);
    }
}
