// Crypto agility: algorithm chosen by policy and recorded with the output, never hard-coded at call sites
public interface ISigningService
{
    Task<SignatureEnvelope> SignAsync(ReadOnlyMemory<byte> data, string purpose, CancellationToken ct);
    Task<bool> VerifyAsync(ReadOnlyMemory<byte> data, SignatureEnvelope sig, CancellationToken ct);
}

public sealed record SignatureEnvelope(string Algorithm, string KeyId, byte[] Signature);   // e.g. "ES256" today, "ML-DSA-65" later

public sealed class PolicySigningService(ICryptoPolicy policy, IKeyProvider keys) : ISigningService
{
    public async Task<SignatureEnvelope> SignAsync(ReadOnlyMemory<byte> data, string purpose, CancellationToken ct)
    {
        var alg = policy.SigningAlgorithmFor(purpose);           // configuration, with a planned migration date per purpose
        var key = await keys.GetSigningKeyAsync(purpose, alg, ct);
        return new SignatureEnvelope(alg, key.Id, await key.SignAsync(data, ct));
    }
    public async Task<bool> VerifyAsync(ReadOnlyMemory<byte> data, SignatureEnvelope sig, CancellationToken ct) =>
        policy.IsAccepted(sig.Algorithm) && await (await keys.GetVerificationKeyAsync(sig.KeyId, ct)).VerifyAsync(data, sig.Signature, ct);
}
